contracts/AccessControl.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title AccessControl Contract for EduChain dApp
 * @dev Manages role-based access control for teachers, students, and admins
 */
contract EduChainAccessControl is AccessControl, ReentrancyGuard {

    // Define role constants
    bytes32 public constant ADMIN_ROLE = DEFAULT_ADMIN_ROLE;
    bytes32 public constant TEACHER_ROLE = keccak256("TEACHER_ROLE");
    bytes32 public constant STUDENT_ROLE = keccak256("STUDENT_ROLE");

    // Events for role management
    event TeacherRegistered(address indexed teacher, address indexed admin);
    event StudentRegistered(address indexed student, address indexed admin);

    // Mapping to track registration timestamps
    mapping(address => uint256) public registrationTime;
    mapping(bytes32 => address[]) private roleMembers;

    constructor(address admin) {
        require(admin != address(0), "Admin address cannot be zero");

        // Grant admin role to the contract deployer
        _grantRole(ADMIN_ROLE, admin);
        _grantRole(ADMIN_ROLE, msg.sender); // Also grant to deployer for setup

        registrationTime[admin] = block.timestamp;
        registrationTime[msg.sender] = block.timestamp;
    }

    /**
     * @dev Register a new teacher (Admin only)
     * @param teacher Address of the teacher to register
     */
    function registerTeacher(address teacher) external onlyRole(ADMIN_ROLE) {
        require(teacher != address(0), "Teacher address cannot be zero");
        require(!hasRole(TEACHER_ROLE, teacher), "Address already has teacher role");

        _grantRole(TEACHER_ROLE, teacher);
        registrationTime[teacher] = block.timestamp;
        roleMembers[TEACHER_ROLE].push(teacher);

        emit TeacherRegistered(teacher, msg.sender);
    }

    /**
     * @dev Register a new student (Admin or Teacher)
     * @param student Address of the student to register
     */
    function registerStudent(address student) external {
        require(
            hasRole(ADMIN_ROLE, msg.sender) || hasRole(TEACHER_ROLE, msg.sender),
            "Only admin or teacher can register students"
        );
        require(student != address(0), "Student address cannot be zero");
        require(!hasRole(STUDENT_ROLE, student), "Address already has student role");

        _grantRole(STUDENT_ROLE, student);
        registrationTime[student] = block.timestamp;
        roleMembers[STUDENT_ROLE].push(student);

        emit StudentRegistered(student, msg.sender);
    }

    /**
     * @dev Revoke teacher role (Admin only)
     * @param teacher Address of the teacher to revoke
     */
    function revokeTeacher(address teacher) external onlyRole(ADMIN_ROLE) {
        require(hasRole(TEACHER_ROLE, teacher), "Address does not have teacher role");

        _revokeRole(TEACHER_ROLE, teacher);
        _removeFromRoleMembers(TEACHER_ROLE, teacher);

        emit RoleRevoked(TEACHER_ROLE, teacher, msg.sender);
    }

    /**
     * @dev Revoke student role (Admin only)
     * @param student Address of the student to revoke
     */
    function revokeStudent(address student) external onlyRole(ADMIN_ROLE) {
        require(hasRole(STUDENT_ROLE, student), "Address does not have student role");

        _revokeRole(STUDENT_ROLE, student);
        _removeFromRoleMembers(STUDENT_ROLE, student);

        emit RoleRevoked(STUDENT_ROLE, student, msg.sender);
    }

    /**
     * @dev Get all teachers
     * @return Array of teacher addresses
     */
    function getAllTeachers() external view returns (address[] memory) {
        return _getActiveRoleMembers(TEACHER_ROLE);
    }

    /**
     * @dev Get all students
     * @return Array of student addresses
     */
    function getAllStudents() external view returns (address[] memory) {
        return _getActiveRoleMembers(STUDENT_ROLE);
    }

    /**
     * @dev Check if an address is a verified teacher
     * @param account Address to check
     * @return bool True if address has teacher role
     */
    function isTeacher(address account) external view returns (bool) {
        return hasRole(TEACHER_ROLE, account);
    }

    /**
     * @dev Check if an address is a verified student
     * @param account Address to check
     * @return bool True if address has student role
     */
    function isStudent(address account) external view returns (bool) {
        return hasRole(STUDENT_ROLE, account);
    }

    /**
     * @dev Check if an address is an admin
     * @param account Address to check
     * @return bool True if address has admin role
     */
    function isAdmin(address account) external view returns (bool) {
        return hasRole(ADMIN_ROLE, account);
    }

    /**
     * @dev Get user's primary role
     * @param account Address to check
     * @return string User's role (admin, teacher, student, or none)
     */
    function getUserRole(address account) external view returns (string memory) {
        if (hasRole(ADMIN_ROLE, account)) return "admin";
        if (hasRole(TEACHER_ROLE, account)) return "teacher";
        if (hasRole(STUDENT_ROLE, account)) return "student";
        return "none";
    }

    /**
     * @dev Get registration timestamp for an address
     * @param account Address to check
     * @return uint256 Registration timestamp
     */
    function getRegistrationTime(address account) external view returns (uint256) {
        return registrationTime[account];
    }

    // Internal function to remove address from role members array
    function _removeFromRoleMembers(bytes32 role, address account) internal {
        address[] storage members = roleMembers[role];
        for (uint256 i = 0; i < members.length; i++) {
            if (members[i] == account) {
                members[i] = members[members.length - 1];
                members.pop();
                break;
            }
        }
    }

    // Internal function to get active role members (filters out revoked roles)
    function _getActiveRoleMembers(bytes32 role) internal view returns (address[] memory) {
        address[] memory allMembers = roleMembers[role];
        uint256 activeCount = 0;

        // Count active members
        for (uint256 i = 0; i < allMembers.length; i++) {
            if (hasRole(role, allMembers[i])) {
                activeCount++;
            }
        }

        // Create array with active members only
        address[] memory activeMembers = new address[](activeCount);
        uint256 index = 0;

        for (uint256 i = 0; i < allMembers.length; i++) {
            if (hasRole(role, allMembers[i])) {
                activeMembers[index] = allMembers[i];
                index++;
            }
        }

        return activeMembers;
    }

    /**
     * @dev Emergency function to update contract (Admin only)
     * Can be used to migrate to new contract versions
     */
    function emergencyPause() external onlyRole(ADMIN_ROLE) {
        // Implementation for emergency pause if needed
        // This is a placeholder for future emergency functionality
    }
}

contracts/AssignmentSubmission.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./AccessControl.sol";
import "./BatchManagement.sol";

/**
 * @title Assignment Submission Contract for EduChain dApp
 * @dev Handles assignment creation, submissions, and IPFS hash storage with batch management
 */
contract AssignmentSubmission {

    EduChainAccessControl public accessControl;
    BatchManagement public batchManagement;

    struct Assignment {
        uint256 id;
        string title;
        string description;
        string ipfsHash; // For assignment instructions
        uint256 deadline;
        uint256 tokenReward;
        address teacher;
        uint256 batchId; // Batch this assignment belongs to
        bool isActive;
        uint256 createdAt;
    }

    struct Submission {
        uint256 id;
        uint256 assignmentId;
        address student;
        string fileName;
        string ipfsHash; // Student's submitted file
        uint256 submissionTime;
        bool isReviewed;
        string grade; // A, B, C, D, F
        string feedback;
        address reviewedBy;
        uint256 reviewedAt;
        uint256 tokensAwarded;
    }

    // Storage
    mapping(uint256 => Assignment) public assignments;
    mapping(uint256 => Submission) public submissions;
    mapping(uint256 => uint256[]) public assignmentSubmissions; // assignmentId => submissionIds[]
    mapping(address => uint256[]) public studentSubmissions; // student => submissionIds[]
    mapping(address => uint256[]) public teacherAssignments; // teacher => assignmentIds[]

    uint256 public nextAssignmentId = 1;
    uint256 public nextSubmissionId = 1;

    // Events
    event AssignmentCreated(
        uint256 indexed assignmentId,
        address indexed teacher,
        string title,
        uint256 deadline,
        uint256 tokenReward
    );

    event AssignmentSubmitted(
        uint256 indexed submissionId,
        uint256 indexed assignmentId,
        address indexed student,
        string ipfsHash,
        uint256 submissionTime
    );

    event SubmissionReviewed(
        uint256 indexed submissionId,
        address indexed reviewer,
        string grade,
        uint256 tokensAwarded
    );

    event AssignmentDeactivated(uint256 indexed assignmentId, address indexed teacher);

    constructor(address _accessControl, address _batchManagement) {
        require(_accessControl != address(0), "Access control address cannot be zero");
        require(_batchManagement != address(0), "Batch management address cannot be zero");
        accessControl = EduChainAccessControl(_accessControl);
        batchManagement = BatchManagement(_batchManagement);
    }

    modifier onlyTeacher() {
        require(accessControl.isTeacher(msg.sender), "Only teachers can perform this action");
        _;
    }

    modifier onlyStudent() {
        require(accessControl.isStudent(msg.sender), "Only students can perform this action");
        _;
    }

    modifier onlyTeacherOrAdmin() {
        require(
            accessControl.isTeacher(msg.sender) || accessControl.isAdmin(msg.sender),
            "Only teachers or admins can perform this action"
        );
        _;
    }

    /**
     * @dev Create a new assignment for a specific batch (Teacher only)
     */
    function createAssignment(
        string memory _title,
        string memory _description,
        string memory _ipfsHash,
        uint256 _deadline,
        uint256 _tokenReward,
        uint256 _batchId
    ) external onlyTeacher returns (uint256) {
        require(bytes(_title).length > 0, "Title cannot be empty");
        require(_deadline > block.timestamp, "Deadline must be in the future");
        require(_tokenReward > 0, "Token reward must be greater than 0");

        // Verify teacher owns the batch
        require(_isTeacherBatch(msg.sender, _batchId), "Teacher does not own this batch");

        uint256 assignmentId = nextAssignmentId++;

        assignments[assignmentId] = Assignment({
            id: assignmentId,
            title: _title,
            description: _description,
            ipfsHash: _ipfsHash,
            deadline: _deadline,
            tokenReward: _tokenReward,
            teacher: msg.sender,
            batchId: _batchId,
            isActive: true,
            createdAt: block.timestamp
        });

        teacherAssignments[msg.sender].push(assignmentId);

        emit AssignmentCreated(assignmentId, msg.sender, _title, _deadline, _tokenReward);

        return assignmentId;
    }

    /**
     * @dev Submit an assignment (Student only)
     */
    function submitAssignment(
        uint256 _assignmentId,
        string memory _fileName,
        string memory _ipfsHash
    ) external onlyStudent returns (uint256) {
        Assignment storage assignment = assignments[_assignmentId];
        require(assignment.isActive, "Assignment is not active");
        require(block.timestamp <= assignment.deadline, "Assignment deadline has passed");
        require(bytes(_fileName).length > 0, "File name cannot be empty");
        require(bytes(_ipfsHash).length > 0, "IPFS hash cannot be empty");

        // Check if student belongs to the assignment's batch
        require(
            batchManagement.isStudentInBatch(msg.sender, assignment.batchId),
            "Student is not enrolled in the required batch for this assignment"
        );

        // Check if student has already submitted this assignment
        require(!hasStudentSubmitted(_assignmentId, msg.sender), "Student has already submitted this assignment");

        uint256 submissionId = nextSubmissionId++;

        submissions[submissionId] = Submission({
            id: submissionId,
            assignmentId: _assignmentId,
            student: msg.sender,
            fileName: _fileName,
            ipfsHash: _ipfsHash,
            submissionTime: block.timestamp,
            isReviewed: false,
            grade: "",
            feedback: "",
            reviewedBy: address(0),
            reviewedAt: 0,
            tokensAwarded: 0
        });

        assignmentSubmissions[_assignmentId].push(submissionId);
        studentSubmissions[msg.sender].push(submissionId);

        emit AssignmentSubmitted(submissionId, _assignmentId, msg.sender, _ipfsHash, block.timestamp);

        return submissionId;
    }

    /**
     * @dev Review and grade a submission (Teacher only)
     */
    function reviewSubmission(
        uint256 _submissionId,
        string memory _grade,
        string memory _feedback,
        uint256 _tokensAwarded
    ) external onlyTeacherOrAdmin {
        Submission storage submission = submissions[_submissionId];
        require(submission.id != 0, "Submission does not exist");
        require(!submission.isReviewed, "Submission already reviewed");

        Assignment storage assignment = assignments[submission.assignmentId];

        // Verify teacher can review this submission (must own the batch)
        require(
            batchManagement.verifyTeacherStudentBatch(msg.sender, submission.student, assignment.batchId) ||
            accessControl.isAdmin(msg.sender),
            "Teacher can only review submissions from their own batch"
        );

        // Validate grade
        require(
            keccak256(bytes(_grade)) == keccak256(bytes("A")) ||
            keccak256(bytes(_grade)) == keccak256(bytes("B")) ||
            keccak256(bytes(_grade)) == keccak256(bytes("C")) ||
            keccak256(bytes(_grade)) == keccak256(bytes("D")) ||
            keccak256(bytes(_grade)) == keccak256(bytes("F")),
            "Invalid grade. Must be A, B, C, D, or F"
        );

        require(_tokensAwarded <= assignment.tokenReward, "Tokens awarded cannot exceed assignment reward");

        submission.isReviewed = true;
        submission.grade = _grade;
        submission.feedback = _feedback;
        submission.reviewedBy = msg.sender;
        submission.reviewedAt = block.timestamp;
        submission.tokensAwarded = _tokensAwarded;

        emit SubmissionReviewed(_submissionId, msg.sender, _grade, _tokensAwarded);
    }

    /**
     * @dev Check if student has already submitted an assignment
     */
    function hasStudentSubmitted(uint256 _assignmentId, address _student) public view returns (bool) {
        uint256[] memory submissionIds = assignmentSubmissions[_assignmentId];

        for (uint256 i = 0; i < submissionIds.length; i++) {
            if (submissions[submissionIds[i]].student == _student) {
                return true;
            }
        }

        return false;
    }

    /**
     * @dev Get assignment details
     */
    function getAssignment(uint256 _assignmentId) external view returns (Assignment memory) {
        return assignments[_assignmentId];
    }

    /**
     * @dev Get submission details
     */
    function getSubmission(uint256 _submissionId) external view returns (Submission memory) {
        return submissions[_submissionId];
    }

    /**
     * @dev Get all submissions for an assignment
     */
    function getAssignmentSubmissions(uint256 _assignmentId) external view returns (uint256[] memory) {
        return assignmentSubmissions[_assignmentId];
    }

    /**
     * @dev Get all submissions by a student
     */
    function getStudentSubmissions(address _student) external view returns (uint256[] memory) {
        return studentSubmissions[_student];
    }

    /**
     * @dev Get all assignments created by a teacher
     */
    function getTeacherAssignments(address _teacher) external view returns (uint256[] memory) {
        return teacherAssignments[_teacher];
    }

    /**
     * @dev Get pending submissions for review (Teacher only)
     */
    function getPendingSubmissions() external view onlyTeacherOrAdmin returns (uint256[] memory) {
        // Get all assignments by this teacher
        uint256[] memory teacherAssignmentIds = teacherAssignments[msg.sender];

        // Count pending submissions
        uint256 pendingCount = 0;
        for (uint256 i = 0; i < teacherAssignmentIds.length; i++) {
            uint256[] memory submissionIds = assignmentSubmissions[teacherAssignmentIds[i]];
            for (uint256 j = 0; j < submissionIds.length; j++) {
                if (!submissions[submissionIds[j]].isReviewed) {
                    pendingCount++;
                }
            }
        }

        // Create array of pending submission IDs
        uint256[] memory pendingSubmissions = new uint256[](pendingCount);
        uint256 index = 0;

        for (uint256 i = 0; i < teacherAssignmentIds.length; i++) {
            uint256[] memory submissionIds = assignmentSubmissions[teacherAssignmentIds[i]];
            for (uint256 j = 0; j < submissionIds.length; j++) {
                if (!submissions[submissionIds[j]].isReviewed) {
                    pendingSubmissions[index] = submissionIds[j];
                    index++;
                }
            }
        }

        return pendingSubmissions;
    }

    /**
     * @dev Deactivate an assignment (Teacher only)
     */
    function deactivateAssignment(uint256 _assignmentId) external onlyTeacher {
        Assignment storage assignment = assignments[_assignmentId];
        require(assignment.teacher == msg.sender, "Only assignment creator can deactivate");
        require(assignment.isActive, "Assignment is already inactive");

        assignment.isActive = false;

        emit AssignmentDeactivated(_assignmentId, msg.sender);
    }

    /**
     * @dev Get total submissions count
     */
    function getTotalSubmissions() external view returns (uint256) {
        return nextSubmissionId - 1;
    }

    /**
     * @dev Get assignments for a specific batch
     */
    function getBatchAssignments(uint256 _batchId) external view returns (uint256[] memory) {
        uint256 count = 0;

        // Count assignments for this batch
        for (uint256 i = 1; i < nextAssignmentId; i++) {
            if (assignments[i].batchId == _batchId && assignments[i].isActive) {
                count++;
            }
        }

        // Create array with batch assignments
        uint256[] memory batchAssignments = new uint256[](count);
        uint256 index = 0;

        for (uint256 i = 1; i < nextAssignmentId; i++) {
            if (assignments[i].batchId == _batchId && assignments[i].isActive) {
                batchAssignments[index] = i;
                index++;
            }
        }

        return batchAssignments;
    }

    /**
     * @dev Get student's assignments from their batches
     */
    function getStudentAvailableAssignments(address _student) external view returns (uint256[] memory) {
        uint256[] memory studentBatches = batchManagement.getStudentBatches(_student);
        uint256 count = 0;

        // Count assignments from all student's batches
        for (uint256 i = 0; i < studentBatches.length; i++) {
            uint256 batchId = studentBatches[i];
            for (uint256 j = 1; j < nextAssignmentId; j++) {
                if (assignments[j].batchId == batchId && assignments[j].isActive) {
                    count++;
                }
            }
        }

        // Create array with available assignments
        uint256[] memory availableAssignments = new uint256[](count);
        uint256 index = 0;

        for (uint256 i = 0; i < studentBatches.length; i++) {
            uint256 batchId = studentBatches[i];
            for (uint256 j = 1; j < nextAssignmentId; j++) {
                if (assignments[j].batchId == batchId && assignments[j].isActive) {
                    availableAssignments[index] = j;
                    index++;
                }
            }
        }

        return availableAssignments;
    }

    /**
     * @dev Internal function to verify teacher owns a batch
     */
    function _isTeacherBatch(address _teacher, uint256 _batchId) internal view returns (bool) {
        try batchManagement.getBatch(_batchId) returns (BatchManagement.Batch memory batch) {
            return batch.teacher == _teacher && batch.isActive;
        } catch {
            return false;
        }
    }

    /**
     * @dev Get total assignments count
     */
    function getTotalAssignments() external view returns (uint256) {
        return nextAssignmentId - 1;
    }
}

contracts/BatchManagement.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./AccessControl.sol";

/**
 * @title Batch Management Contract for EduChain dApp
 * @dev Manages student batches created by teachers
 */
contract BatchManagement {

    EduChainAccessControl public accessControl;

    struct Batch {
        uint256 id;
        string name;
        address teacher;
        address[] students;
        bool isActive;
        uint256 createdAt;
        uint256 updatedAt;
    }

    // Storage
    mapping(uint256 => Batch) public batches;
    mapping(address => uint256[]) public teacherBatches; // teacher => batchIds[]
    mapping(address => mapping(uint256 => bool)) public studentInBatch; // student => batchId => isInBatch
    mapping(address => uint256[]) public studentBatches; // student => batchIds[]

    uint256 public nextBatchId = 1;

    // Events
    event BatchCreated(
        uint256 indexed batchId,
        address indexed teacher,
        string name,
        uint256 timestamp
    );

    event StudentAddedToBatch(
        uint256 indexed batchId,
        address indexed student,
        address indexed teacher,
        uint256 timestamp
    );

    event StudentRemovedFromBatch(
        uint256 indexed batchId,
        address indexed student,
        address indexed teacher,
        uint256 timestamp
    );

    event BatchDeactivated(
        uint256 indexed batchId,
        address indexed teacher,
        uint256 timestamp
    );

    event BatchRenamed(
        uint256 indexed batchId,
        string oldName,
        string newName,
        address indexed teacher,
        uint256 timestamp
    );

    constructor(address _accessControl) {
        require(_accessControl != address(0), "Access control address cannot be zero");
        accessControl = EduChainAccessControl(_accessControl);
    }

    modifier onlyTeacher() {
        require(accessControl.isTeacher(msg.sender), "Only teachers can perform this action");
        _;
    }

    modifier onlyBatchTeacher(uint256 _batchId) {
        require(batches[_batchId].teacher == msg.sender, "Only the batch creator can manage this batch");
        require(batches[_batchId].isActive, "Batch is not active");
        _;
    }

    modifier validBatch(uint256 _batchId) {
        require(_batchId > 0 && _batchId < nextBatchId, "Invalid batch ID");
        require(batches[_batchId].isActive, "Batch is not active");
        _;
    }

    /**
     * @dev Create a new batch (Teacher only)
     */
    function createBatch(string memory _name) external onlyTeacher returns (uint256) {
        require(bytes(_name).length > 0, "Batch name cannot be empty");
        require(bytes(_name).length <= 100, "Batch name too long");

        uint256 batchId = nextBatchId++;

        batches[batchId] = Batch({
            id: batchId,
            name: _name,
            teacher: msg.sender,
            students: new address[](0),
            isActive: true,
            createdAt: block.timestamp,
            updatedAt: block.timestamp
        });

        teacherBatches[msg.sender].push(batchId);

        emit BatchCreated(batchId, msg.sender, _name, block.timestamp);

        return batchId;
    }

    /**
     * @dev Add a student to a batch (Only batch teacher)
     */
    function addStudentToBatch(uint256 _batchId, address _student) 
        external 
        onlyBatchTeacher(_batchId) 
    {
        require(_student != address(0), "Student address cannot be zero");
        require(accessControl.isStudent(_student), "Address must be a registered student");
        require(!studentInBatch[_student][_batchId], "Student already in this batch");

        Batch storage batch = batches[_batchId];
        batch.students.push(_student);
        batch.updatedAt = block.timestamp;

        studentInBatch[_student][_batchId] = true;
        studentBatches[_student].push(_batchId);

        emit StudentAddedToBatch(_batchId, _student, msg.sender, block.timestamp);
    }

    /**
     * @dev Add multiple students to a batch (Only batch teacher)
     */
    function addMultipleStudentsToBatch(uint256 _batchId, address[] memory _students) 
        external 
        onlyBatchTeacher(_batchId) 
    {
        require(_students.length > 0, "Students array cannot be empty");
        require(_students.length <= 50, "Too many students in one transaction");

        Batch storage batch = batches[_batchId];

        for (uint256 i = 0; i < _students.length; i++) {
            address student = _students[i];

            require(student != address(0), "Student address cannot be zero");
            require(accessControl.isStudent(student), "Address must be a registered student");

            if (!studentInBatch[student][_batchId]) {
                batch.students.push(student);
                studentInBatch[student][_batchId] = true;
                studentBatches[student].push(_batchId);

                emit StudentAddedToBatch(_batchId, student, msg.sender, block.timestamp);
            }
        }

        batch.updatedAt = block.timestamp;
    }

    /**
     * @dev Remove a student from a batch (Only batch teacher)
     */
    function removeStudentFromBatch(uint256 _batchId, address _student) 
        external 
        onlyBatchTeacher(_batchId) 
    {
        require(studentInBatch[_student][_batchId], "Student not in this batch");

        Batch storage batch = batches[_batchId];

        // Remove from students array
        for (uint256 i = 0; i < batch.students.length; i++) {
            if (batch.students[i] == _student) {
                batch.students[i] = batch.students[batch.students.length - 1];
                batch.students.pop();
                break;
            }
        }

        // Remove from student's batch list
        uint256[] storage studentBatchList = studentBatches[_student];
        for (uint256 i = 0; i < studentBatchList.length; i++) {
            if (studentBatchList[i] == _batchId) {
                studentBatchList[i] = studentBatchList[studentBatchList.length - 1];
                studentBatchList.pop();
                break;
            }
        }

        studentInBatch[_student][_batchId] = false;
        batch.updatedAt = block.timestamp;

        emit StudentRemovedFromBatch(_batchId, _student, msg.sender, block.timestamp);
    }

    /**
     * @dev Rename a batch (Only batch teacher)
     */
    function renameBatch(uint256 _batchId, string memory _newName) 
        external 
        onlyBatchTeacher(_batchId) 
    {
        require(bytes(_newName).length > 0, "Batch name cannot be empty");
        require(bytes(_newName).length <= 100, "Batch name too long");

        Batch storage batch = batches[_batchId];
        string memory oldName = batch.name;
        batch.name = _newName;
        batch.updatedAt = block.timestamp;

        emit BatchRenamed(_batchId, oldName, _newName, msg.sender, block.timestamp);
    }

    /**
     * @dev Deactivate a batch (Only batch teacher)
     */
    function deactivateBatch(uint256 _batchId) 
        external 
        onlyBatchTeacher(_batchId) 
    {
        Batch storage batch = batches[_batchId];
        batch.isActive = false;
        batch.updatedAt = block.timestamp;

        // Remove all students from batch
        for (uint256 i = 0; i < batch.students.length; i++) {
            address student = batch.students[i];
            studentInBatch[student][_batchId] = false;

            // Remove from student's batch list
            uint256[] storage studentBatchList = studentBatches[student];
            for (uint256 j = 0; j < studentBatchList.length; j++) {
                if (studentBatchList[j] == _batchId) {
                    studentBatchList[j] = studentBatchList[studentBatchList.length - 1];
                    studentBatchList.pop();
                    break;
                }
            }
        }

        emit BatchDeactivated(_batchId, msg.sender, block.timestamp);
    }

    /**
     * @dev Check if a student is in a specific batch
     */
    function isStudentInBatch(address _student, uint256 _batchId) 
        external 
        view 
        returns (bool) 
    {
        return studentInBatch[_student][_batchId];
    }

    /**
     * @dev Get batch details
     */
    function getBatch(uint256 _batchId) 
        external 
        view 
        validBatch(_batchId) 
        returns (Batch memory) 
    {
        return batches[_batchId];
    }

    /**
     * @dev Get students in a batch
     */
    function getBatchStudents(uint256 _batchId) 
        external 
        view 
        validBatch(_batchId) 
        returns (address[] memory) 
    {
        return batches[_batchId].students;
    }

    /**
     * @dev Get batches created by a teacher
     */
    function getTeacherBatches(address _teacher) 
        external 
        view 
        returns (uint256[] memory) 
    {
        return teacherBatches[_teacher];
    }

    /**
     * @dev Get batches a student belongs to
     */
    function getStudentBatches(address _student) 
        external 
        view 
        returns (uint256[] memory) 
    {
        return studentBatches[_student];
    }

    /**
     * @dev Get active batches for a teacher
     */
    function getActiveTeacherBatches(address _teacher) 
        external 
        view 
        returns (uint256[] memory) 
    {
        uint256[] memory allBatches = teacherBatches[_teacher];
        uint256 activeCount = 0;

        // Count active batches
        for (uint256 i = 0; i < allBatches.length; i++) {
            if (batches[allBatches[i]].isActive) {
                activeCount++;
            }
        }

        // Create array with active batches only
        uint256[] memory activeBatches = new uint256[](activeCount);
        uint256 index = 0;

        for (uint256 i = 0; i < allBatches.length; i++) {
            if (batches[allBatches[i]].isActive) {
                activeBatches[index] = allBatches[i];
                index++;
            }
        }

        return activeBatches;
    }

    /**
     * @dev Get batch statistics
     */
    function getBatchStats(uint256 _batchId) 
        external 
        view 
        validBatch(_batchId) 
        returns (
            string memory name,
            address teacher,
            uint256 studentCount,
            uint256 createdAt,
            uint256 updatedAt
        ) 
    {
        Batch storage batch = batches[_batchId];
        return (
            batch.name,
            batch.teacher,
            batch.students.length,
            batch.createdAt,
            batch.updatedAt
        );
    }

    /**
     * @dev Get total number of batches
     */
    function getTotalBatches() external view returns (uint256) {
        return nextBatchId - 1;
    }

    /**
     * @dev Verify teacher can manage student in batch (for external contracts)
     */
    function verifyTeacherStudentBatch(
        address _teacher, 
        address _student, 
        uint256 _batchId
    ) external view returns (bool) {
        if (!batches[_batchId].isActive) return false;
        if (batches[_batchId].teacher != _teacher) return false;
        return studentInBatch[_student][_batchId];
    }
}

contracts/TokenReward.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./AccessControl.sol";
import "./BatchManagement.sol";

/**
 * @title EduChain Token Reward System
 * @dev Non-transferable ERC20 token for academic rewards
 */
contract EduChainToken is ERC20, Ownable, ReentrancyGuard {

    EduChainAccessControl public accessControl;
    BatchManagement public batchManagement;

    // Token is non-transferable for academic integrity
    bool public transfersEnabled = false;

    // Mapping to track token earnings by assignment
    mapping(address => mapping(uint256 => uint256)) public assignmentEarnings;
    mapping(address => uint256[]) public studentAssignmentIds;
    mapping(address => uint256) public totalEarnings;

    // Grade to token multiplier (A=100%, B=80%, C=60%, D=40%, F=0%)
    mapping(string => uint256) public gradeMultipliers;

    struct TokenTransaction {
        address student;
        uint256 assignmentId;
        uint256 amount;
        string grade;
        address awardedBy;
        uint256 timestamp;
        string transactionType; // "assignment_reward", "bonus", "penalty"
    }

    TokenTransaction[] public tokenTransactions;
    mapping(address => uint256[]) public studentTransactions;

    event TokensAwarded(
        address indexed student,
        uint256 indexed assignmentId,
        uint256 amount,
        string grade,
        address indexed awardedBy
    );

    event TokensBurned(address indexed student, uint256 amount, string reason);

    event GradeMultiplierUpdated(string grade, uint256 multiplier);

    constructor(
        address _accessControl,
        address _batchManagement,
        address _owner
    ) ERC20("EduChain Token", "EDU") Ownable(_owner) {
        require(_accessControl != address(0), "Access control address cannot be zero");
        require(_batchManagement != address(0), "Batch management address cannot be zero");
        require(_owner != address(0), "Owner address cannot be zero");

        accessControl = EduChainAccessControl(_accessControl);
        batchManagement = BatchManagement(_batchManagement);

        // Initialize grade multipliers (percentage in basis points: 10000 = 100%)
        gradeMultipliers["A"] = 10000; // 100%
        gradeMultipliers["B"] = 8000;  // 80%
        gradeMultipliers["C"] = 6000;  // 60%
        gradeMultipliers["D"] = 4000;  // 40%
        gradeMultipliers["F"] = 0;     // 0%
    }

    modifier onlyTeacherOrAdmin() {
        require(
            accessControl.isTeacher(msg.sender) || accessControl.isAdmin(msg.sender),
            "Only teachers or admins can award tokens"
        );
        _;
    }

    modifier onlyStudent(address account) {
        require(accessControl.isStudent(account), "Account must be a registered student");
        _;
    }

    /**
     * @dev Award tokens to student based on assignment grade (with batch verification)
     */
    function awardTokens(
        address _student,
        uint256 _assignmentId,
        uint256 _batchId,
        uint256 _baseAmount,
        string memory _grade
    ) external onlyTeacherOrAdmin onlyStudent(_student) nonReentrant {
        require(_baseAmount > 0, "Base amount must be greater than 0");
        require(gradeMultipliers[_grade] >= 0, "Invalid grade");
        require(assignmentEarnings[_student][_assignmentId] == 0, "Tokens already awarded for this assignment");

        // Verify teacher can award tokens to this student for this batch
        require(
            batchManagement.verifyTeacherStudentBatch(msg.sender, _student, _batchId) ||
            accessControl.isAdmin(msg.sender),
            "Teacher can only award tokens to students in their batch"
        );

        // Calculate actual tokens based on grade
        uint256 actualAmount = (_baseAmount * gradeMultipliers[_grade]) / 10000;

        if (actualAmount > 0) {
            _mint(_student, actualAmount);

            assignmentEarnings[_student][_assignmentId] = actualAmount;
            totalEarnings[_student] += actualAmount;

            // Track assignment for student
            studentAssignmentIds[_student].push(_assignmentId);

            // Record transaction
            TokenTransaction memory transaction = TokenTransaction({
                student: _student,
                assignmentId: _assignmentId,
                amount: actualAmount,
                grade: _grade,
                awardedBy: msg.sender,
                timestamp: block.timestamp,
                transactionType: "assignment_reward"
            });

            tokenTransactions.push(transaction);
            studentTransactions[_student].push(tokenTransactions.length - 1);

            emit TokensAwarded(_student, _assignmentId, actualAmount, _grade, msg.sender);
        }
    }

    /**
     * @dev Award bonus tokens (Admin only)
     */
    function awardBonusTokens(
        address _student,
        uint256 _amount,
        string memory _reason
    ) external onlyOwner onlyStudent(_student) nonReentrant {
        require(_amount > 0, "Amount must be greater than 0");

        _mint(_student, _amount);
        totalEarnings[_student] += _amount;

        // Record transaction with assignmentId = 0 for bonus
        TokenTransaction memory transaction = TokenTransaction({
            student: _student,
            assignmentId: 0,
            amount: _amount,
            grade: "BONUS",
            awardedBy: msg.sender,
            timestamp: block.timestamp,
            transactionType: "bonus"
        });

        tokenTransactions.push(transaction);
        studentTransactions[_student].push(tokenTransactions.length - 1);

        emit TokensAwarded(_student, 0, _amount, "BONUS", msg.sender);
    }

    /**
     * @dev Burn tokens (Admin only, for penalties)
     */
    function burnTokens(
        address _student,
        uint256 _amount,
        string memory _reason
    ) external onlyOwner onlyStudent(_student) nonReentrant {
        require(balanceOf(_student) >= _amount, "Insufficient balance to burn");

        _burn(_student, _amount);

        // Record penalty transaction
        TokenTransaction memory transaction = TokenTransaction({
            student: _student,
            assignmentId: 0,
            amount: _amount,
            grade: "PENALTY",
            awardedBy: msg.sender,
            timestamp: block.timestamp,
            transactionType: "penalty"
        });

        tokenTransactions.push(transaction);
        studentTransactions[_student].push(tokenTransactions.length - 1);

        emit TokensBurned(_student, _amount, _reason);
    }

    /**
     * @dev Update grade multiplier (Admin only)
     */
    function updateGradeMultiplier(string memory _grade, uint256 _multiplier) external onlyOwner {
        require(_multiplier <= 10000, "Multiplier cannot exceed 100%");
        gradeMultipliers[_grade] = _multiplier;
        emit GradeMultiplierUpdated(_grade, _multiplier);
    }

    /**
     * @dev Get student's earnings for specific assignment
     */
    function getAssignmentEarnings(address _student, uint256 _assignmentId) external view returns (uint256) {
        return assignmentEarnings[_student][_assignmentId];
    }

    /**
     * @dev Get all assignments where student earned tokens
     */
    function getStudentAssignments(address _student) external view returns (uint256[] memory) {
        return studentAssignmentIds[_student];
    }

    /**
     * @dev Get student's total earnings
     */
    function getTotalEarnings(address _student) external view returns (uint256) {
        return totalEarnings[_student];
    }

    /**
     * @dev Get student's transaction history
     */
    function getStudentTransactions(address _student) external view returns (uint256[] memory) {
        return studentTransactions[_student];
    }

    /**
     * @dev Get transaction details
     */
    function getTransaction(uint256 _transactionId) external view returns (TokenTransaction memory) {
        require(_transactionId < tokenTransactions.length, "Transaction does not exist");
        return tokenTransactions[_transactionId];
    }

    /**
     * @dev Get total number of transactions
     */
    function getTotalTransactions() external view returns (uint256) {
        return tokenTransactions.length;
    }

    /**
     * @dev Get grade multiplier
     */
    function getGradeMultiplier(string memory _grade) external view returns (uint256) {
        return gradeMultipliers[_grade];
    }

    // Override transfer functions to make tokens non-transferable
    function transfer(address to, uint256 amount) public override returns (bool) {
        require(transfersEnabled || msg.sender == owner(), "Transfers are disabled for academic integrity");
        return super.transfer(to, amount);
    }

    function transferFrom(address from, address to, uint256 amount) public override returns (bool) {
        require(transfersEnabled || msg.sender == owner(), "Transfers are disabled for academic integrity");
        return super.transferFrom(from, to, amount);
    }

    /**
     * @dev Enable/disable transfers (Admin only, for emergency use)
     */
    function setTransfersEnabled(bool _enabled) external onlyOwner {
        transfersEnabled = _enabled;
    }

    /**
     * @dev Emergency function to mint tokens (Admin only)
     */
    function emergencyMint(address _to, uint256 _amount) external onlyOwner {
        _mint(_to, _amount);
    }

    /**
     * @dev Check if tokens are transferable
     */
    function areTransfersEnabled() external view returns (bool) {
        return transfersEnabled;
    }
}

